unitsize(0.6 cm);

real func (real x) {
  return (2*(x - 1)/(x + 2));
}

int i;

for (i = -8; i <= 8; ++i) {
  draw((i,-8)--(i,8),gray(0.7));
  draw((-8,i)--(8,i),gray(0.7));
}

draw((-8,0)--(8,0));
