draw((sqrt(3),0)--origin--(0,1)--cycle);
real r1 = (sqrt(3) - 1)/2;
draw(Circle((r1,r1),r1));
label("$A$",(sqrt(3),0),SE);
label("$B$",(0,1),NW);
label("$O$",(r1,r1),ESE);
label("$C$",(0,r1),W);
